function longestIncreasingPath(matrix: number[][]): number {
  if (matrix.length === 0) return 0;
  const m = matrix.length;
  const n = matrix[0].length;

  const visited = Array.from({ length: m }).map(() => Array.from({ length: n }).fill(false)) as boolean[][];
  let count = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      count = Math.max(search(matrix, i, j, visited), count);
    }
  }

  return count;
};

const directions = [
  [-1, 0],
  [0, -1],
  [1, 0],
  [0, 1]
]

function search(matrix: number[][], i: number, j: number, visited: boolean[][], acc = 0): number {
  if (visited[i][j]) return acc;
  const m = matrix.length;
  const n = matrix[0].length;

  visited[i][j] = true;
  let max = acc + 1;
  for (let dir of directions) {
    const nextRow = i + dir[0];
    const nextCol = j + dir[1];
    if (nextRow >= 0 && nextRow < m && nextCol >= 0 && nextCol < n && matrix[nextRow][nextCol] > matrix[i][j]) {
      max = Math.max(search(matrix, nextRow, nextCol, visited, acc + 1), max);
    }
  }

  visited[i][j] = false;

  return max;
}

