const directions = [
  [-1, 0],
  [0, -1],
  [1, 0],
  [0, 1]
]

function search(matrix: number[][], i: number, j: number, memo: number[][]): number {
  if (memo[i][j]) return memo[i][j];
  const m = matrix.length;
  const n = matrix[0].length;

  let max = 1;
  for (let dir of directions) {
    const nextRow = i + dir[0];
    const nextCol = j + dir[1];
    if (nextRow >= 0 && nextRow < m && nextCol >= 0 && nextCol < n && matrix[nextRow][nextCol] > matrix[i][j]) {
      max = Math.max(search(matrix, nextRow, nextCol, memo) + 1, max);
    }
  }

  memo[i][j] = max;

  return max;
}
